@CrossOrigin
@RestController
@RequestMapping("/ObservationQuery")
public class ObservationQueryRestController extends BaseSpringRestController {
	
	public ObservationQueryRestController( ObservationService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Observation using a UUID
     * @param		UUID observationId
     * @return		Observation
     */    
    @GetMapping("/load")
    public Observation load( @RequestParam(required=true) UUID observationId ) {
    	Observation entity = null;

    	try {  
    		entity = service.getObservation( new ObservationFetchOneSummary( observationId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Observation using Id " + observationId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Observation business objects
     * @return		Set<Observation>
     */
    @GetMapping("/")
    public List<Observation> loadAll() {                
    	List<Observation> observationList = null;
        
    	try {
            // load the Observation
            observationList = service.getAllObservation();
            
            if ( observationList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Observations" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Observations ", exc );
        	return null;
        }

        return observationList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Observation observation = null;
    protected ObservationService service = null;
    private static final Logger LOGGER = Logger.getLogger(ObservationQueryRestController.class.getName());
    
}
